package com.citacloud.springboot.contacloud.app.models;
import jakarta.persistence.*;import java.math.BigDecimal;import java.util.UUID;
@Entity @Table(name="saved_sale_line") public class LineaVentaGuardada {
 @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="tenant_id",nullable=false,updatable=false)private UUID tenantId;@Column(name="empresa_id",nullable=false,updatable=false)private UUID empresaId;@Column(name="saved_sale_id",nullable=false,updatable=false)private UUID ventaId;@Column(name="product_id",nullable=false)private UUID productoId;
 @Column(name="product_code",nullable=false,length=24)private String codigo;@Column(name="product_name",nullable=false,length=300)private String nombre;@Column(name="unit_name",nullable=false,length=80)private String unidad;
 @Column(nullable=false,precision=19,scale=4)private BigDecimal cantidad;@Column(nullable=false,precision=19,scale=4)private BigDecimal precio;@Column(name="tax_rate",nullable=false,precision=9,scale=6)private BigDecimal tasaImpuesto;@Column(nullable=false,precision=19,scale=4)private BigDecimal subtotal;@Column(nullable=false,precision=19,scale=4)private BigDecimal impuesto;@Column(nullable=false,precision=19,scale=4)private BigDecimal total;@Column(name="line_order",nullable=false)private int orden;
 @Column(name="allow_discounts_snapshot",nullable=false)private boolean permiteDescuentos;@Column(name="discount_amount",nullable=false,precision=19,scale=4)private BigDecimal descuento;@Column(name="taxable_base_amount",nullable=false,precision=19,scale=4)private BigDecimal baseImponible;
 @Column(name="allow_surcharges_snapshot",nullable=false)private boolean permiteRecargos;@Column(name="surcharge_amount",nullable=false,precision=19,scale=4)private BigDecimal recargo=BigDecimal.ZERO;
 @Column(name="source_quote_line_id")private UUID cotizacionLineaOrigenId;
 protected LineaVentaGuardada(){}public LineaVentaGuardada(VentaGuardada venta,Producto producto,String unidad,BigDecimal cantidad,BigDecimal precio,BigDecimal tasa,BigDecimal subtotal,BigDecimal impuesto,BigDecimal total,int orden){this(venta,producto,unidad,cantidad,precio,tasa,subtotal,BigDecimal.ZERO,subtotal,impuesto,total,orden);}
 public LineaVentaGuardada(VentaGuardada venta,Producto producto,String unidad,BigDecimal cantidad,BigDecimal precio,BigDecimal tasa,BigDecimal subtotal,BigDecimal descuento,BigDecimal baseImponible,BigDecimal impuesto,BigDecimal total,int orden){this(venta,producto,unidad,cantidad,precio,tasa,subtotal,descuento,BigDecimal.ZERO,baseImponible,impuesto,total,orden);}
 public LineaVentaGuardada(VentaGuardada venta,Producto producto,String unidad,BigDecimal cantidad,BigDecimal precio,BigDecimal tasa,BigDecimal subtotal,BigDecimal descuento,BigDecimal recargo,BigDecimal baseImponible,BigDecimal impuesto,BigDecimal total,int orden){tenantId=venta.getTenantId();empresaId=venta.getEmpresaId();ventaId=venta.getId();productoId=producto.getId();codigo=producto.getCodigo();nombre=producto.getNombre();this.unidad=unidad;this.cantidad=cantidad;this.precio=precio;tasaImpuesto=tasa;this.subtotal=subtotal;this.permiteDescuentos=producto.isPermiteDescuentos();this.permiteRecargos=producto.isPermiteRecargos();this.descuento=descuento;this.recargo=recargo;this.baseImponible=baseImponible;this.impuesto=impuesto;this.total=total;this.orden=orden;}
 public void cotizacionLineaOrigen(UUID id){cotizacionLineaOrigenId=id;}
 public UUID getId(){return id;}public UUID getProductoId(){return productoId;}public String getCodigo(){return codigo;}public String getNombre(){return nombre;}public String getUnidad(){return unidad;}public BigDecimal getCantidad(){return cantidad;}public BigDecimal getPrecio(){return precio;}public BigDecimal getTasaImpuesto(){return tasaImpuesto;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getImpuesto(){return impuesto;}public BigDecimal getTotal(){return total;}public int getOrden(){return orden;}
 public boolean isPermiteDescuentos(){return permiteDescuentos;}public BigDecimal getDescuento(){return descuento;}public BigDecimal getBaseImponible(){return baseImponible;}
 public boolean isPermiteRecargos(){return permiteRecargos;}public BigDecimal getRecargo(){return recargo;}
 public UUID getCotizacionLineaOrigenId(){return cotizacionLineaOrigenId;}
}
